"""CodexAgent -- a `codex exec` BaseInstalledAgent for the external bench: generated
CODEX_HOME provider config, one non-interactive turn, event stream mapped to ATIF."""
from __future__ import annotations

import base64
import json
import shlex
from pathlib import Path

from harbor.agents.installed.base import BaseInstalledAgent
from harbor.environments.base import BaseEnvironment
from harbor.models.agent.context import AgentContext
from harbor.models.trajectories.agent import Agent
from harbor.models.trajectories.final_metrics import FinalMetrics
from harbor.models.trajectories.metrics import Metrics
from harbor.models.trajectories.step import Step
from harbor.models.trajectories.tool_call import ToolCall
from harbor.models.trajectories.trajectory import Trajectory

from workbuddy_bench.agents._agent_user import ensure_agent_user

_OUTPUT_FILENAME = "codex-output.jsonl"
_STDERR_FILENAME = "codex-stderr.log"

# Must not collide with a built-in codex provider id, or the config would override that
# provider instead of defining a new one.
_PROVIDER_ID = "wbbench_bridge"

_CODEX_HOME_SUBDIR = ".codex-adapt"

_ITEM_TEXT_TYPES = ("agent_message",)
_ITEM_REASONING_TYPES = ("reasoning",)


class CodexAgent(BaseInstalledAgent):
    """Codex CLI agent (installed-CLI harness) for harbor."""

    SUPPORTS_ATIF: bool = True

    def __init__(self, logs_dir: Path, *args, **kwargs):
        self._codex_version: str | None = kwargs.pop("CODEX_VERSION", None)
        kwargs.pop("CODEX_MAX_TURNS", None)
        self._bin_dir = str(kwargs.pop("CODEX_BIN_DIR", "/opt/codex")).rstrip("/")
        # The model id codex sends to the bridge: the bridge's own model list, not the
        # bench route slug, because the request never traverses the bench proxy.
        self._codex_model = str(kwargs.pop("CODEX_MODEL", ""))
        model_params = kwargs.pop("model_params", None) or {}
        self._max_output_tokens = model_params.get("max_output_tokens")
        effort = kwargs.pop("CODEX_REASONING_EFFORT", None)
        if effort is None:
            extra_body = model_params.get("extra_body") or {}
            effort = extra_body.get("reasoning_effort")
        self._reasoning_effort: str | None = str(effort) if effort else None
        connection = kwargs.pop("connection", None) or {}
        self._conn_mode = str(connection.get("mode") or "direct")
        cw = kwargs.pop("context_window", None)
        self._context_window: int | None = int(cw) if cw is not None else None
        kwargs.pop("context_compact_pct", None)
        kwargs.pop("settings_preset", None)
        kwargs.pop("models_preset", None)
        kwargs.pop("mount_path", None)
        kwargs.pop("instance_id", None)
        super().__init__(logs_dir, *args, version=self._codex_version, **kwargs)

    @staticmethod
    def name() -> str:
        return "codex"

    def get_version_command(self) -> str | None:
        return 'export PATH="/opt/codex/codex-path:/usr/local/bin:$PATH"; codex --version'

    def parse_version(self, stdout: str) -> str:
        out = (stdout or "").strip()
        return out.split()[-1] if out else out

    async def install(self, environment: BaseEnvironment) -> None:
        """Link the bind-mounted binary onto PATH and refuse anything but the pinned build."""
        bin_path = f"{self._bin_dir}/codex"
        want = self._codex_version or ""
        await self.exec_as_root(
            environment,
            command=(
                f'if [ ! -x "{bin_path}" ]; then '
                f'echo "ERROR: codex binary not found at {bin_path}." >&2; '
                f'echo "  The job must bind-mount the staged dist (read-only):" >&2; '
                f'echo "  environment_override.mounts: [{{type: bind, '
                f'source: dependencies/codex/dist, target: {self._bin_dir}}}]" >&2; '
                f"exit 1; fi && "
                f'ln -sf "{bin_path}" /usr/local/bin/codex && '
                f'v="$(/usr/local/bin/codex --version 2>&1)" && '
                f'echo "codex version: $v" && '
                + (
                    f'case "$v" in *"{want}"*) : ;; *) '
                    f'echo "ERROR: mounted codex is \'$v\', pinned CODEX_VERSION is '
                    f'{want}. Refusing to run an unpinned build — point '
                    f'the Codex mount at a staged {want} dist or repin the '
                    f'harness version." >&2; '
                    f"exit 1;; esac"
                    if want else "true"
                )
            ),
        )
        await ensure_agent_user(self, environment)

    def _config_toml(self, bridge_url: str) -> str:
        """The per-run CODEX_HOME config.toml — the validated provider shape."""
        lines = [
            "# GENERATED by workbuddy_bench.agents.codex_agent — per-run, container-local.",
            f'model = "{self._codex_model}"',
            f'model_provider = "{_PROVIDER_ID}"',
        ]
        if self._context_window is not None:
            lines.append(f"model_context_window = {int(self._context_window)}")
        if self._max_output_tokens is not None:
            lines.append(f"model_max_output_tokens = {int(self._max_output_tokens)}")
        lines += [
            "",
            f"[model_providers.{_PROVIDER_ID}]",
            'name = "WorkBuddy Bench codex bridge"',
            f'base_url = "{bridge_url}"',
            'wire_api = "responses"',
            'env_key = "VERTEX_PROXY_KEY"',
            "",
            # Match the bench's websearch deny: it is the one tool that can leak the
            # bench's own materials into a rollout.
            "[tools]",
            "web_search = false",
            "",
        ]
        return "\n".join(lines)

    async def run(
        self, instruction: str, environment: BaseEnvironment, context: AgentContext
    ) -> None:
        instruction = self.render_instruction(instruction)

        bridge_url = (self._get_env("CODEX_BRIDGE_URL") or "").strip().rstrip("/")
        if not bridge_url:
            raise RuntimeError(
                "CODEX_BRIDGE_URL is not set for codex-harness — the harness "
                "version yaml must provide it (host litellm Responses bridge as "
                "seen from inside the container, e.g. "
                "https://your-responses-endpoint/v1).")
        if not self._has_env("VERTEX_PROXY_KEY"):
            raise RuntimeError(
                "VERTEX_PROXY_KEY is not set — the job must inject it via "
                "env_override; codex reads it through the provider block's "
                "env_key and sends it as the bridge bearer token.")

        config_b64 = base64.b64encode(self._config_toml(bridge_url).encode()).decode()
        await self._run_codex(environment, config_b64,
                              escaped_instruction=shlex.quote(instruction))

    async def _run_codex(
        self, environment: BaseEnvironment, config_b64: str, *,
        escaped_instruction: str,
    ) -> None:
        """Write config.toml into the container and run one `codex exec` turn."""
        # `docker exec -u <user>` inherits a baked ENV HOME the agent user may not be able
        # to write, so HOME is re-derived from the running user's passwd entry.
        home_fix = 'export HOME="$(getent passwd "$(id -u)" | cut -d: -f6)"; '
        codex_home = f'"$HOME/{_CODEX_HOME_SUBDIR}"'
        setup_cmd = (
            f"{home_fix}"
            f"mkdir -p {codex_home} && "
            f"echo {config_b64} | base64 -d > {codex_home}/config.toml"
        )
        await self.exec_as_agent(environment, command=setup_cmd)

        output_path = f"/logs/agent/{_OUTPUT_FILENAME}"
        stderr_path = f"/logs/agent/{_STDERR_FILENAME}"
        flags = [
            "--model", shlex.quote(self._codex_model),
        ]
        if self._reasoning_effort:
            flags += ["-c", shlex.quote(f'model_reasoning_effort="{self._reasoning_effort}"')]
        flags += [
            "--skip-git-repo-check",
            "--dangerously-bypass-approvals-and-sandbox",
            # without this flag codex runs but silently skips .codex/hooks.json
            "--dangerously-bypass-hook-trust",
            "--ephemeral",
            "--json",
            "-C", "/workspace",
            "--add-dir", "/workspace",
        ]
        run_cmd = (
            'export PATH="/opt/codex/codex-path:/usr/local/bin:$PATH"; '
            f"{home_fix}"
            f"export CODEX_HOME={codex_home}; "
            f"codex exec {escaped_instruction} {' '.join(flags)} "
            f"</dev/null 2>{stderr_path} | tee {output_path}"
        )
        await self.exec_as_agent(environment, command=run_cmd)

    def populate_context_post_run(self, context: AgentContext) -> None:
        events = self._read_events()
        if events is None:
            return
        trajectory = self._build_trajectory(events)
        if trajectory:
            traj_path = self.logs_dir / "trajectory.json"
            try:
                with open(traj_path, "w", encoding="utf-8") as fh:
                    json.dump(trajectory.to_json_dict(), fh, indent=2, ensure_ascii=False)
            except (OSError, AttributeError) as exc:
                self.logger.debug("Failed writing trajectory.json: %s", exc)
            fm = trajectory.final_metrics
            if fm:
                context.n_input_tokens = fm.total_prompt_tokens or 0
                context.n_output_tokens = fm.total_completion_tokens or 0
                context.n_cache_tokens = fm.total_cached_tokens or 0
                if fm.total_cost_usd is not None:
                    context.cost_usd = fm.total_cost_usd

    def _read_events(self) -> list[dict] | None:
        out = self.logs_dir / _OUTPUT_FILENAME
        if not out.is_file():
            self.logger.warning(
                "codex output not found: %s — token/cost context will be empty "
                "(check the /logs/agent mount)", out)
            return None
        events: list[dict] = []
        try:
            for line in out.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if not line.startswith("{"):
                    continue
                try:
                    ev = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if isinstance(ev, dict):
                    events.append(ev)
        except OSError as exc:
            self.logger.debug("Failed reading codex output: %s", exc)
            return None
        return events

    @staticmethod
    def _item_tool_call(item: dict) -> ToolCall | None:
        """Map a completed thread item to an ATIF ToolCall, or None for text/reasoning."""
        itype = item.get("type", "")
        iid = str(item.get("id") or "")
        if itype == "command_execution":
            return ToolCall(tool_call_id=iid, function_name="shell",
                            arguments={"command": str(item.get("command") or "")})
        if itype == "mcp_tool_call":
            return ToolCall(
                tool_call_id=iid,
                function_name=f"{item.get('server', 'mcp')}.{item.get('tool', 'tool')}",
                arguments=item.get("arguments") if isinstance(item.get("arguments"), dict) else {})
        if itype == "file_change":
            changes = item.get("changes")
            return ToolCall(tool_call_id=iid, function_name="apply_patch",
                            arguments={"changes": changes} if changes is not None else {})
        if itype == "web_search":
            return ToolCall(tool_call_id=iid, function_name="web_search",
                            arguments={"query": str(item.get("query") or "")})
        return None

    def _build_trajectory(self, events: list[dict]) -> Trajectory | None:
        """Map codex's ``exec --json`` stream to an ATIF Trajectory.

        One Step per ``turn.completed`` boundary, accumulating the ``item.completed``
        events since the previous one; totals are summed across turns. Trailing items with
        no closing turn still become a final Step, with no metrics and no reasoning_content,
        which ATIF forbids when ``llm_call_count == 0``.
        """
        steps: list[Step] = []
        text_parts: list[str] = []
        reasoning_parts: list[str] = []
        tool_calls: list[ToolCall] = []
        session_id: str | None = None
        total_in = total_out = total_cache = 0
        errors: list = []
        tool_errors = 0
        step_id = 1

        def flush(metrics: Metrics | None) -> None:
            nonlocal text_parts, reasoning_parts, tool_calls, step_id
            reasoning = "\n".join(p for p in reasoning_parts if p) or None
            steps.append(Step(
                step_id=step_id,
                source="agent",
                model_name=self._codex_model,
                message="\n".join(p for p in text_parts if p),
                reasoning_content=reasoning if metrics else None,
                tool_calls=tool_calls or None,
                metrics=metrics,
                llm_call_count=1 if metrics else 0,
            ))
            text_parts, reasoning_parts, tool_calls = [], [], []
            step_id += 1

        for ev in events:
            etype = ev.get("type")
            session_id = session_id or ev.get("thread_id")
            if etype == "item.completed":
                item = ev.get("item") if isinstance(ev.get("item"), dict) else {}
                itype = item.get("type", "")
                if itype in _ITEM_TEXT_TYPES:
                    txt = item.get("text")
                    if isinstance(txt, str) and txt.strip():
                        text_parts.append(txt)
                elif itype in _ITEM_REASONING_TYPES:
                    txt = item.get("text") or item.get("summary") or ""
                    if isinstance(txt, str) and txt.strip():
                        reasoning_parts.append(txt)
                elif itype == "error":
                    errors.append({"message": item.get("message")})
                else:
                    tc = self._item_tool_call(item)
                    if tc is not None:
                        tool_calls.append(tc)
                        status = item.get("status")
                        exit_code = item.get("exit_code")
                        if status == "failed" or (exit_code not in (None, 0)):
                            tool_errors += 1
            elif etype == "turn.completed":
                usage = ev.get("usage") if isinstance(ev.get("usage"), dict) else {}
                t_in = int(usage.get("input_tokens") or 0)
                t_out = int(usage.get("output_tokens") or 0)
                t_cache = int(usage.get("cached_input_tokens") or 0)
                total_in += t_in
                total_out += t_out
                total_cache += t_cache
                flush(Metrics(prompt_tokens=t_in, completion_tokens=t_out))
            elif etype in ("turn.failed", "error"):
                err = ev.get("error") or {"message": ev.get("message")}
                if err:
                    errors.append(err)

        if text_parts or reasoning_parts or tool_calls:
            flush(None)

        if not steps and not errors:
            return None
        if not steps:
            # ATIF requires >= 1 step, so a run that died before producing one records why.
            steps.append(Step(
                step_id=1,
                source="agent",
                model_name=self._codex_model,
                message=f"run produced no steps; {len(errors)} error event(s): "
                        + "; ".join(json.dumps(e)[:300] for e in errors[:3]),
                llm_call_count=0,
            ))

        extra: dict = {"steps": len(steps), "tool_errors": tool_errors,
                       "model_route": self.model_name, "conn_mode": self._conn_mode}
        if errors:
            extra["codex_errors"] = errors

        final_metrics = FinalMetrics(
            total_prompt_tokens=total_in,
            total_completion_tokens=total_out,
            total_cached_tokens=total_cache,
            total_cost_usd=None,        # the bridge does not report cost
            total_steps=len(steps),
            extra=extra,
        )

        notes = (
            "codex exec --json emits no run-level total event, so totals are summed "
            "across turn.completed usage records (output_tokens is the billed output, "
            "reasoning included). One Step = one turn.completed boundary; only "
            "item.completed events are consumed (started/updated are progressive "
            "states of the same item)."
        )
        if errors:
            notes += f" RUN REPORTED {len(errors)} error event(s); see extra.codex_errors."

        return Trajectory(
            session_id=session_id,
            agent=Agent(name="codex", version=self._version or "unknown",
                        model_name=self._codex_model),
            steps=steps,
            final_metrics=final_metrics,
            notes=notes,
        )
